/* Trace directed weighted graph operations with deterministic sorted output. */
#include <cstddef>
#include <cstdint>
namespace {void put(std::uint8_t*out,std::size_t i,std::int64_t v){auto bits=static_cast<std::uint64_t>(v);for(std::size_t b=0;b<8;++b)out[i*8+b]=static_cast<std::uint8_t>(bits>>(8*b));}}
extern "C" std::int64_t graph_lua_directed_weighted(const std::int64_t*in,std::size_t len,std::uint8_t*out,std::size_t cap) noexcept{
 if(!in||len<2)return -1;auto nv=in[0],ov=in[1];if(nv<1||nv>16||ov<0||ov>63||len!=static_cast<std::size_t>(2+4*ov))return -1;auto n=static_cast<std::size_t>(nv),ops=static_cast<std::size_t>(ov);int kind[16][16]{};std::int64_t weight[16][16]{},rtype[63]{},rvalue[63]{};
 for(std::size_t i=0;i<ops;++i){auto op=in[2+4*i],a=in[3+4*i],b=in[4+4*i],v=in[5+4*i];if(op<0||op>5||a<0||a>=nv||b<0||b>=nv)return -1;auto x=static_cast<std::size_t>(a),y=static_cast<std::size_t>(b);if(op==0){if(v< -1000||v>1000)return -1;kind[x][y]=2;weight[x][y]=v;rtype[i]=-1;}else if(op==1){if(v!=0)return -1;kind[x][y]=1;rtype[i]=-1;rvalue[i]=0;}else if(op==2){if(v!=0)return -1;kind[x][y]=0;weight[x][y]=0;rtype[i]=-1;rvalue[i]=0;}else if(op==3){if(v!=0||kind[x][y]!=0)return -1;kind[x][y]=1;weight[x][y]=0;rtype[i]=-1;rvalue[i]=0;}else if(op==4){if(v!=0)return -1;rtype[i]=kind[x][y];rvalue[i]=kind[x][y]==2?weight[x][y]:0;}else{if(v!=0)return -1;rtype[i]=kind[x][y]!=0?1:0;rvalue[i]=0;}}
 std::size_t edges=0;for(std::size_t a=0;a<n;++a)for(std::size_t b=0;b<n;++b)if(kind[a][b])++edges;auto words=2+2*ops+4*edges;if(!out||cap<words*8)return -2;std::size_t k=0;put(out,k++,static_cast<std::int64_t>(ops));for(std::size_t i=0;i<ops;++i){put(out,k++,rtype[i]);put(out,k++,rvalue[i]);}put(out,k++,static_cast<std::int64_t>(edges));for(std::size_t a=0;a<n;++a)for(std::size_t b=0;b<n;++b)if(kind[a][b]){put(out,k++,static_cast<std::int64_t>(a));put(out,k++,static_cast<std::int64_t>(b));put(out,k++,kind[a][b]);put(out,k++,weight[a][b]);}return static_cast<std::int64_t>(words*8);
}
